import './language.js';
import{domain,inputAdvice,selector,explain,records,candidates,CheckSession}from'./core.js';
const $=id=>document.getElementById(id);const checker=new CheckSession();
const labels={MX:['MX',15],SPF:['TXT',16],DMARC:['TXT',16],DKIM:['TXT',16]};
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;if(cls==='record')e.dataset.l10nRaw='';return e;}
function stop(message){checker.cancel();$('cancel').hidden=true;$('check').disabled=false;if(message)$('status').textContent=message;}
function render(name,results,demo=false){$('results').hidden=false;$('result-domain').textContent=name;$('mode').textContent=demo?'Fictional demo · no network requests':'Live · Cloudflare 1.1.1.1';$('freshness').textContent=demo?'Illustrative records, not current DNS':'Observed '+new Date().toLocaleString()+' · snapshot only';$('cards').replaceChildren();const infos=Object.keys(labels).map(kind=>({kind,...explain(kind,results[kind])}));
 const concerns=infos.filter(i=>i.state==='Needs attention'),unavailable=infos.filter(i=>i.state==='Unavailable'),limited=infos.filter(i=>['Unavailable','Tool limitation'].includes(i.state)),missing=infos.filter(i=>['Not found here','Incomplete'].includes(i.state)),notFound=infos.some(i=>i.state==='Domain not found');
 $('overview').replaceChildren(node('h3',notFound?'Check the domain spelling first':unavailable.length===Object.keys(results).length?'DNS answers unavailable: setup could not be assessed':concerns.length?'What we found: configuration concerns to review':limited.length?'Some checks could not be completed':missing.length?'Some records were not found or need a closer look':'What we found in public DNS'));
 const list=node('ul');const names={MX:'Incoming mail',SPF:'Sending permission',DMARC:'Policy for failing messages',DKIM:'Signing key'};
 for(const info of infos){const line=node('li');line.append(node('strong',names[info.kind]+' — '+info.state+': '));let finding=info.title;
 if(info.kind==='MX'&&info.state==='Observed'){const destinations=records(results.MX,15).map(r=>r.text.replace(/^\d+\s+/,'').replace(/\.$/,''));finding='Published routing destination'+(destinations.length===1?'':'s')+': '+destinations.slice(0,3).join(', ')+(destinations.length>3?' (and '+(destinations.length-3)+' more)':'')+'. These hosts are not tested.';}
 if(info.kind==='SPF'&&info.brief)finding+=': '+info.brief;
 if(info.kind==='DKIM'&&info.state==='Records found')finding='Signing key candidate found for the supplied selector. Key syntax and message signatures were not validated.';
 if(info.kind==='DKIM'&&info.state==='Not checked')finding='Skipped because no selector was supplied. This does not mean a key is missing.';
 if(notFound&&['DMARC','DKIM'].includes(info.kind)){line.append(node('span','Resolve the domain-name issue before interpreting this check.'));}else{line.append(node('span',finding),node('small',info.next));}list.append(line);}
 $('overview').append(list);
 for(const kind of Object.keys(labels)){const result=results[kind],info=explain(kind,result),card=node('article',undefined,'card');const top=node('div',undefined,'card-top');top.append(node('h3',kind),node('span',info.state,'badge'+(['Needs attention','Domain not found'].includes(info.state)?' attention':'')));card.append(top,node('h4',info.title),node('p',result?.error?'The request was unavailable. Check your connection or retry later. Raw diagnostic details remain below.':info.body));if(result){let rows=[];try{rows=records(result,labels[kind][1]);}catch{}const relevant=candidates(kind,rows);if(rows.length>relevant.length)card.append(node('p',`${rows.length-relevant.length} unrelated TXT record(s) retained in raw evidence.`));const published=node('details',undefined,'evidence');published.append(node('summary','Published records'));for(const row of relevant){const record=node('div',row.text,'record');record.append(node('small',`${row.name} · TTL ${row.TTL}s`));published.append(record);}if(relevant.length)card.append(published);}const next=node('div',undefined,'next');next.append(node('strong','Next useful step'),node('span',info.next));card.append(next);if(result){const evidence=node('details',undefined,'evidence');evidence.append(node('summary','Raw resolver evidence'));evidence.append(node('p',`${result.name} · ${result.type} · ${result.observed||'fictional fixture'}${result.bytes!==undefined?' · '+result.bytes+' bytes':''}`));evidence.append(node('p',demo?'Demo values are invented.':`Cloudflare DNS status ${result.Status??'unavailable'} · DNSSEC AD flag ${result.AD===true?'true':'not true'} (not an independent validation). TTL describes resolver cache lifetime, not global propagation or guaranteed freshness.`));evidence.append(node('pre',JSON.stringify(result,null,2)));card.append(evidence);} $('cards').append(card);}}
$('form').addEventListener('submit',async event=>{
 event.preventDefault();stop();$('error').textContent='';if(!$('purpose-dns').checked){$('results').hidden=true;$('error').textContent='Choose whether you need mailbox help or intend to inspect public domain records first.';$('status').textContent='No DNS query was made.';return;}$('input-advice').hidden=true;$('results').hidden=true;let name,sel;let errorField='domain';$('status').textContent='';
 try{const advice=inputAdvice($('domain').value);name=advice.name;if(advice.kind!=='domain'){$('input-advice').hidden=false;$('use-domain').hidden=false;$('input-message').replaceChildren(node('span',advice.knownProvider?`${name} is managed by its email provider. Its DNS report cannot evaluate your account or explain a missing message. For mailbox help, choose the first option above. `:''),node('span',`You chose public DNS inspection. This checks public records for ${name}, not this mailbox, and does not establish that you control the domain. Compare results with provider setup instructions; changes require the DNS administrator. If you need help with your account or a message, choose mailbox help instead. Only the domain will be sent to the resolver.`));$('use-domain').textContent=`Inspect ${name} DNS only`;$('use-domain').onclick=()=>{$('domain').value=name;$('form').requestSubmit();};$('status').textContent='Confirm the domain-only inspection, or choose mailbox help. No DNS query was made.';$('use-domain').focus();return;}errorField='selector';sel=selector($('selector').value);if(sel&&`${sel}._domainkey.${name}`.length>253)throw Error('Domain plus DKIM selector is too long.');}
 catch(e){$('error').textContent=e.message;$(errorField).focus();return;}
 $('domain').value=name;$('results').hidden=true;$('cancel').hidden=false;$('check').disabled=true;
 $('status').textContent=`Checking ${name} with Cloudflare…`;
 const tasks=[['MX',name,'MX'],['SPF',name,'TXT'],['DMARC','_dmarc.'+name,'TXT'],...(sel?[['DKIM',sel+'._domainkey.'+name,'TXT']]:[])];
 const results=await checker.run(tasks);if(results===null)return;
 $('cancel').hidden=true;$('check').disabled=false;render(name,results);
 $('status').textContent='Check finished. Read each observation and its limits below.';
});
for(const id of ['purpose-mailbox','purpose-dns'])$(id).addEventListener('change',()=>{stop();$('results').hidden=true;$('input-advice').hidden=true;$('error').textContent='';$('purpose-help').hidden=true;const dns=$('purpose-dns').checked;$('dns-fields').hidden=!dns;$('demo-row').hidden=!dns;$('mailbox-help').hidden=dns;$('status').textContent=dns?'Public DNS inspection selected. No query until you explicitly check.':'Mailbox help selected. This help makes no DNS queries.';});
$('domain').addEventListener('input',()=>{$('input-advice').hidden=true;});
$('cancel').onclick=()=>stop('Cancelled. No results from this check will be shown.');
$('clear').onclick=()=>{stop();$('form').reset();$('dns-fields').hidden=true;$('demo-row').hidden=true;$('mailbox-help').hidden=true;$('purpose-help').hidden=false;$('input-advice').hidden=true;$('results').hidden=true;$('cards').replaceChildren();$('error').textContent='';$('status').textContent='Cleared. Nothing was saved.';$('purpose-mailbox').focus();};
$('demo').onclick=()=>{if(!$('purpose-dns').checked)return;stop();$('input-advice').hidden=true;$('error').textContent='';const sample=(name,type,Answer)=>({Status:0,TC:false,AD:false,name,type,Answer});render('studio.example', {MX:sample('studio.example','MX',[{name:'studio.example.',type:15,TTL:3600,data:'10 mail.provider.example.'}]),SPF:sample('studio.example','TXT',[{name:'studio.example.',type:16,TTL:3600,data:'"v=spf1 include:_spf.provider.example -all"'}]),DMARC:sample('_dmarc.studio.example','TXT',[])},true);$('status').textContent='Fictional demo loaded. No DNS query was made.';};
window.addEventListener('pagehide',()=>stop());
